// Custom alphabet Base64 used for optional resource protection.
// This is obfuscation, not encryption: the alphabet is embedded in the
// generated package and determined users can recover it.

const STANDARD_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

export const createAlphabet = () => {
  const alphabet = STANDARD_ALPHABET.split('');
  const random = new Uint32Array(alphabet.length);
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    crypto.getRandomValues(random);
  } else {
    for (let i = 0; i < random.length; i++) random[i] = Math.random() * 0xffffffff;
  }
  for (let i = alphabet.length - 1; i > 0; i--) {
    const j = random[i] % (i + 1);
    const value = alphabet[i];
    alphabet[i] = alphabet[j];
    alphabet[j] = value;
  }
  return alphabet.join('');
};

export const encode = (data, alphabet) => {
  let result = '';
  for (let i = 0; i < data.length; i += 3) {
    const a = data[i];
    const b = i + 1 < data.length ? data[i + 1] : 0;
    const c = i + 2 < data.length ? data[i + 2] : 0;
    const n = (a << 16) | (b << 8) | c;
    result += alphabet[(n >>> 18) & 63];
    result += alphabet[(n >>> 12) & 63];
    result += i + 1 < data.length ? alphabet[(n >>> 6) & 63] : '=';
    result += i + 2 < data.length ? alphabet[n & 63] : '=';
  }
  return result;
};

